package dev.lichen.core

import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import org.junit.jupiter.api.Assumptions.assumeTrue
import java.io.File
import java.util.concurrent.TimeUnit

/** vectors.json, generated by android/tools/gen_vectors.py from the real Python package. */
object Vectors {
    val root: JsonObject by lazy {
        val text = Vectors::class.java.getResourceAsStream("/vectors.json")!!.readBytes().toString(Charsets.UTF_8)
        parseObject(text)!!
    }
    operator fun get(key: String): JsonElement = root.getValue(key)
    fun obj(key: String) = get(key) as JsonObject
    fun arr(key: String) = get(key) as JsonArray
}

fun JsonElement?.str(): String = asString()!!
fun JsonElement?.o(): JsonObject = this as JsonObject
fun JsonElement?.a(): JsonArray = this as JsonArray

/** Runs short scripts with the repo's real Python `lichen` package (skips the test if Python isn't there). */
object Py {
    val repo: String = System.getProperty("lichen.repo") ?: error("lichen.repo not set")
    val exe: String? = listOfNotNull(
        System.getenv("LICHEN_PYTHON"),
        "$repo/.venv/Scripts/python.exe", "$repo/.venv/bin/python",
        "C:/Users/afrik/Github/Lichen/.venv/Scripts/python.exe",
    ).firstOrNull { File(it).exists() }

    fun require() = assumeTrue(exe != null, "no Python with lichen installed; skipping cross-check")

    /** Run [script] (argv[1] = this worktree's repo root, so its lichen/ is imported) with [stdin]; returns stdout. */
    fun run(script: String, stdin: String = ""): String {
        require()
        val prelude = "import sys, json\nsys.path.insert(0, sys.argv[1])\n"
        // Via a file: Windows command lines mangle the double quotes in a -c script.
        val file = File.createTempFile("lichen-check", ".py").also { it.deleteOnExit(); it.writeText(prelude + script, Charsets.UTF_8) }
        val p = ProcessBuilder(exe, "-I", "-X", "utf8", file.absolutePath, repo).redirectErrorStream(true).start()
        val outBuf = java.util.concurrent.atomic.AtomicReference(ByteArray(0))
        val reader = Thread { outBuf.set(p.inputStream.readBytes()) }.also { it.start() }  // drain while we write
        try { p.outputStream.use { it.write(stdin.toByteArray(Charsets.UTF_8)) } } catch (e: java.io.IOException) { /* python died early: report below */ }
        reader.join()
        val out = outBuf.get().toString(Charsets.UTF_8)
        check(p.waitFor(60, TimeUnit.SECONDS)) { "python timed out" }
        check(p.exitValue() == 0) { "python failed:\n$out" }
        return out
    }
}
